 elsif tg_argv[0]='AGREEMENT' then select requester_account_id,worker_account_id into a,b from public.agreements where id=(r->>tg_argv[1])::uuid;
 elsif tg_argv[0]='RESPONSE' then select n.requester_account_id,m.worker_account_id into a,b from public.marketplace_responses m join public.needs n on n.id=m.need_id where m.id=(r->>tg_argv[1])::uuid;
 elsif tg_argv[0]='APPLICATION' then select requester_account_id into a from public.needs where id=(r->>'need_id')::uuid;b:=(r->>'worker_account_id')::uuid;
 else raise exception 'CLOSURE_CONTEXT_INVALID' using errcode='42501'; end if;
 perform private.closure_assert_open(a,b);
 if tg_op='DELETE' then return old; end if;
 return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.set_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
BEGIN
 if auth.role()='service_role' then
  if TG_OP in ('UPDATE','DELETE') and private.closure_redaction_allowed_v5(TG_RELID,TG_OP,to_jsonb(OLD),case when TG_OP='UPDATE' then to_jsonb(NEW) else null end) then
   if TG_OP='DELETE' then return OLD;end if;return NEW;
  end if;
 end if;

  NEW.updated_at = now();
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION private.guard_profile_write()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare
  after_fields jsonb;
  before_fields jsonb := '{}'::jsonb;
  field text;
  validate_all boolean;
  token text := nullif(
    current_setting('uskoci.profile_mutation', true),
    ''
  );
begin
 if auth.role()='service_role' then
  if TG_OP in ('UPDATE','DELETE') and private.closure_redaction_allowed_v5(TG_RELID,TG_OP,to_jsonb(OLD),case when TG_OP='UPDATE' then to_jsonb(NEW) else null end) then
   if TG_OP='DELETE' then return OLD;end if;return NEW;
  end if;
 end if;

  if (tg_op='INSERT' and new.operating_country_code is not null)
    or (tg_op='UPDATE' and new.operating_country_code is distinct from old.operating_country_code) then
    if token is distinct from 'LOCATION_REVIEW' or new.kind is distinct from 'WORKER' then
      raise exception 'PROFILE_COUNTRY_REQUIRES_LOCATION_REVIEW' using errcode='42501';
    end if;
    perform private.require_location_country(to_jsonb(new.operating_country_code));
  end if;
  -- Reuse the same V2 value validator and comparison vocabulary as a Need.
  -- Do not rewrite historical profiles or reject unrelated edits to old data.
  if new.kind = 'WORKER' then
    after_fields := to_jsonb(new);
    validate_all := tg_op = 'INSERT';
    if tg_op = 'UPDATE' then
      before_fields := to_jsonb(old);
      validate_all := old.profile_status = 'DRAFT' and new.profile_status = 'ACTIVE';
    end if;
    foreach field in array array['skills','tools','vehicles','licenses'] loop
      if validate_all or (after_fields->field) is distinct from (before_fields->field) then
        perform private.validate_need_v2_fact('need.required_' || field, after_fields->field);
      end if;
    end loop;
  end if;

  if tg_op = 'INSERT' then
    new.profile_status := case
      when new.kind = 'REQUESTER' then 'ACTIVE'
      when new.kind = 'WORKER' then 'DRAFT'
      else 'DRAFT'
    end;
    new.account_type := 'INDIVIDUAL';
    new.rating_requester := null;
    new.rating_worker := null;
    return new;
  end if;

  if new.account_id is distinct from old.account_id
     or new.kind is distinct from old.kind then
    raise exception 'PROFILE_IDENTITY_IMMUTABLE'
      using errcode = '42501';
  end if;

  if new.profile_status is distinct from old.profile_status then
    if token is distinct from 'COMPLETE_WORKER_PROFILE'
       or old.kind is distinct from 'WORKER'
       or old.profile_status is distinct from 'DRAFT'
       or new.profile_status is distinct from 'ACTIVE' then
      raise exception 'PROFILE_STATUS_IS_SERVER_DERIVED'
        using errcode = '42501';
    end if;
  end if;

  if new.account_type is distinct from old.account_type then
    raise exception 'ACCOUNT_TYPE_IS_SERVER_DERIVED'
      using errcode = '42501';
  end if;

  if new.rating_requester is distinct from old.rating_requester then
    raise exception 'RATING_REQUESTER_IS_SERVER_DERIVED'
      using errcode = '42501';
  end if;

  if new.rating_worker is distinct from old.rating_worker then
    raise exception 'RATING_WORKER_IS_SERVER_DERIVED'
      using errcode = '42501';
  end if;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION private.guard_worker_equipment_retired_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$
begin
 -- This is deliberately SECURITY INVOKER: canonical SECURITY DEFINER erasure
 -- may redact historical data; authenticated REST cannot edit it.
 if current_user='authenticated' and new.kind='WORKER' then
  if tg_op='INSERT' then
   if cardinality(coalesce(new.tools,'{}'::text[]))>0 or cardinality(coalesce(new.vehicles,'{}'::text[]))>0 then
    raise exception 'WORKER_EQUIPMENT_RETIRED' using errcode='22023';
   end if;
  elsif new.tools is distinct from old.tools or new.vehicles is distinct from old.vehicles then
   raise exception 'WORKER_EQUIPMENT_RETIRED' using errcode='22023';
  end if;
 end if;
 return new;
end $function$

CREATE OR REPLACE FUNCTION private.closure_guard_owned_write()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare r jsonb; prior jsonb; a uuid; b uuid;
begin
 if auth.role()='service_role' then
  if TG_OP in ('UPDATE','DELETE') and private.closure_redaction_allowed_v5(TG_RELID,TG_OP,to_jsonb(OLD),case when TG_OP='UPDATE' then to_jsonb(NEW) else null end) then
   if TG_OP='DELETE' then return OLD;end if;return NEW;
  end if;
 end if;

 r:=case when tg_op='DELETE' then to_jsonb(old) else to_jsonb(new) end;
 prior:=case when tg_op='INSERT' then '{}'::jsonb else to_jsonb(old) end;
 if tg_table_name='needs' and tg_op='UPDATE' and (r->>'status') is distinct from (prior->>'status') and (r->>'status') in('CANCELLED','COMPLETED','EXPIRED','ARCHIVED') then return new; end if;
 if tg_table_name='marketplace_responses' and tg_op='UPDATE' and (r->>'status') is distinct from (prior->>'status') and (r->>'status') in('WITHDRAWN','EXPIRED','NOT_SELECTED','STALE') then return new; end if;
 if tg_table_name='agreements' and tg_op='UPDATE' and (r->>'status') is distinct from (prior->>'status') and (r->>'status') in('CANCELLED','COMPLETED') then return new; end if;
 if tg_table_name='agreement_versions' and tg_op='UPDATE' and (r->>'status')='CANCELLED' then return new; end if;
 if tg_table_name='agreement_change_proposals' and tg_op='UPDATE' and (r->>'status') not in('PENDING','ACCEPTED') then return new; end if;
 if tg_table_name='access_grants' and tg_op='UPDATE' and (r->>'status')='REVOKED' then return new; end if;
 if tg_table_name='notification_push_devices' and tg_op='UPDATE' and (r->>'active')::boolean is false
  and (r->>'user_id')=(prior->>'user_id') and (r->>'expo_push_token')=(prior->>'expo_push_token') and (r->>'platform')=(prior->>'platform') then return new; end if;
 if tg_table_name='ai_need_turn_commands' and tg_op='UPDATE' and (prior->>'state')='PROCESSING' and (r->>'state') in('SUCCEEDED','FAILED') then return new; end if;
 -- Export remains a separate request/read/cancel capability; only a new
 -- processing claim is fenced. Existing attempts can settle without new work.
 if tg_table_name='data_export_requests' and (r->>'status')<>'PROCESSING' then
  if tg_op='DELETE' then return old; end if; return new;
 end if;
 if tg_table_name='retention_jobs' and (r->>'status')<>'CLAIMED' then return new; end if;
 if tg_argv[0]='ACCOUNT' then a:=(r->>tg_argv[1])::uuid;
 elsif tg_argv[0]='PROFILE' then select account_id into a from public.app_profiles where id=(r->>tg_argv[1])::uuid;
 elsif tg_argv[0]='NEED' then select requester_account_id into a from public.needs where id=(r->>tg_argv[1])::uuid;
 elsif tg_argv[0]='CONVERSATION' then select account_id into a from public.ai_conversations where id=(r->>tg_argv[1])::uuid;
 elsif tg_argv[0]='PAIR' then a:=(r->>tg_argv[1])::uuid;b:=(r->>tg_argv[2])::uuid;
 elsif tg_argv[0]='AGREEMENT' then select requester_account_id,worker_account_id into a,b from public.agreements where id=(r->>tg_argv[1])::uuid;
 elsif tg_argv[0]='RESPONSE' then select n.requester_account_id,m.worker_account_id into a,b from public.marketplace_responses m join public.needs n on n.id=m.need_id where m.id=(r->>tg_argv[1])::uuid;
 elsif tg_argv[0]='APPLICATION' then select requester_account_id into a from public.needs where id=(r->>'need_id')::uuid;b:=(r->>'worker_account_id')::uuid;
 else raise exception 'CLOSURE_CONTEXT_INVALID' using errcode='42501'; end if;
 perform private.closure_assert_open(a,b);
 if tg_op='DELETE' then return old; end if;
 return new;
end;
$function$

CREATE OR REPLACE FUNCTION private.guard_requester_identity_writer()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
begin
 if auth.role()='service_role' then
  if TG_OP in ('UPDATE','DELETE') and private.closure_redaction_allowed_v5(TG_RELID,TG_OP,to_jsonb(OLD),case when TG_OP='UPDATE' then to_jsonb(NEW) else null end) then
   if TG_OP='DELETE' then return OLD;end if;return NEW;
  end if;
 end if;

 if new.kind='REQUESTER' and auth.role()='authenticated'
   and new.display_name is distinct from old.display_name
   and nullif(current_setting('uskoci.profile_mutation',true),'') is distinct from 'REQUESTER_IDENTITY' then
   raise exception 'REQUESTER_PROFILE_REQUIRES_AUTHORITY' using errcode='42501'; end if;
 return new;
end;
$function$

CREATE OR REPLACE FUNCTION private.guard_worker_fact_authority()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare token text:=nullif(current_setting('uskoci.profile_mutation',true),'');
begin
 if auth.role()='service_role' then
  if TG_OP in ('UPDATE','DELETE') and private.closure_redaction_allowed_v5(TG_RELID,TG_OP,to_jsonb(OLD),case when TG_OP='UPDATE' then to_jsonb(NEW) else null end) then
   if TG_OP='DELETE' then return OLD;end if;return NEW;
  end if;
 end if;

  if new.kind<>'WORKER' or auth.role() is distinct from 'authenticated' then return new; end if;
  if tg_op='INSERT' then
    -- Structural bootstrap defaults are not user choices. Auth signup is a
    -- separate trusted trigger; unprivileged insertion cannot prefill these.
    if (new.city<>'' or new.radius_km<>15) and token is distinct from 'LOCATION_REVIEW' then
      raise exception 'PROFILE_LOCATION_REQUIRES_REVIEW' using errcode='42501';
    end if;
    if new.available_now and token is distinct from 'AVAILABILITY_REVIEW' then
      raise exception 'PROFILE_AVAILABILITY_REQUIRES_REVIEW' using errcode='42501';
    end if;
    if new.team_capacity<>1 and token is distinct from 'CAPACITY_REVIEW' then
      raise exception 'PROFILE_CAPACITY_REQUIRES_REVIEW' using errcode='42501';
    end if;
  else
    if (new.city is distinct from old.city or new.radius_km is distinct from old.radius_km)
       and token is distinct from 'LOCATION_REVIEW' then
      raise exception 'PROFILE_LOCATION_REQUIRES_REVIEW' using errcode='42501';
    end if;
    if new.available_now is distinct from old.available_now and token is distinct from 'AVAILABILITY_REVIEW' then
      raise exception 'PROFILE_AVAILABILITY_REQUIRES_REVIEW' using errcode='42501';
    end if;
    if new.team_capacity is distinct from old.team_capacity and token is distinct from 'CAPACITY_REVIEW' then
      raise exception 'PROFILE_CAPACITY_REQUIRES_REVIEW' using errcode='42501';
    end if;
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION private.worker_profile_sync_taxonomy_capabilities_trg_fn()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'private'
AS $function$
BEGIN
  IF NEW.kind <> 'WORKER' THEN RETURN NEW; END IF;
  IF TG_OP = 'UPDATE' AND NEW.skills IS NOT DISTINCT FROM OLD.skills THEN
    RETURN NEW;
  END IF;
  -- No nonempty check: a zero-skill profile must revoke all active categories.
  PERFORM private.sync_worker_skills_to_taxonomy_capabilities(
    NEW.account_id, COALESCE(NEW.skills, ARRAY[]::text[])
  );
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION private.guard_persistent_availability()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$
begin
 if auth.role()='service_role' then
  if TG_OP in ('UPDATE','DELETE') and private.closure_redaction_allowed_v5(TG_RELID,TG_OP,to_jsonb(OLD),case when TG_OP='UPDATE' then to_jsonb(NEW) else null end) then
   if TG_OP='DELETE' then return OLD;end if;return NEW;
  end if;
 end if;

  new.available_now_expires_at:=null;
  if new.kind='WORKER' and new.profile_status not in ('DRAFT','ACTIVE') then new.available_now:=false; end if;
  return new;
end;
$function$

